-- Datos de demostración para entornos de PRUEBA (no ejecutar en producción).
-- Simula lo que harían ECO y ATLAS con 5 mensajes.
SELECT r4_api('{"op":"set_config","config":{"evolution_url":"https://evolution.example.test","evolution_instancia":"ATLASR4","wa_destino_direccion":"34600000000"}}'::jsonb);

WITH m AS (SELECT (r4_ingest('{"canal":"gmail","external_id":"demo-1","remitente_nombre":"Carmen Vidal","remitente_email":"c.vidal@fincas-portixol.example","asunto":"Solicitud de presupuesto · grietas en vigas del garaje","cuerpo":"Buenos días, somos la administración del edificio de Av. Argentina 41. En la última junta se detectaron grietas en dos vigas del garaje y nos gustaría una visita esta semana. Tel. 600 000 101."}'::jsonb)->>'id')::bigint AS id)
SELECT r4_aplicar_extraccion(jsonb_build_object('id', m.id, 'extraccion', '{"es_cliente":true,"motivo":"Administradora pide visita","nombre":"Carmen Vidal","empresa":"Administración de Fincas Portixol","email":"","telefono":"+34600000101","tipo_cliente":"administrador_fincas","servicio":"Reparación del hormigón armado","solicita":"visita","urgencia":"alta","direccion_obra":"Av. Argentina 41","municipio":"Palma","titulo":"Grietas en vigas del garaje","resumen":"Administra la comunidad de Av. Argentina 41 (Palma). Grietas en dos vigas del garaje. Pide visita esta semana y presupuesto para la junta de diciembre."}'::jsonb)) FROM m;

WITH m AS (SELECT (r4_ingest('{"canal":"gmail","external_id":"demo-2","remitente_nombre":"Antoni Riera","remitente_email":"presidencia.sonferriol@correo.example","asunto":"IEE del edificio · deficiencias estructurales","cuerpo":"Adjuntamos el informe IEE que nos marca deficiencias en pilares de la planta sótano. Queremos saber qué opciones de reparación hay.","adjuntos":1}'::jsonb)->>'id')::bigint AS id)
SELECT r4_aplicar_extraccion(jsonb_build_object('id', m.id, 'extraccion', '{"es_cliente":true,"motivo":"Presidente de comunidad con IEE","nombre":"Antoni Riera","empresa":"CP Son Ferriol","email":"","telefono":"","tipo_cliente":"comunidad","servicio":"IEE / ITE","solicita":"presupuesto","urgencia":"media","direccion_obra":"","municipio":"Palma","titulo":"Deficiencias IEE en pilares del sótano","resumen":"Presidente de CP Son Ferriol. El IEE marca deficiencias en pilares del sótano. Pide opciones de reparación y presupuesto orientativo; adjunta el informe."}'::jsonb)) FROM m;

WITH m AS (SELECT (r4_ingest('{"canal":"gmail","external_id":"demo-3","remitente_nombre":"Morteros Técnicos","remitente_email":"news@proveedor.example","asunto":"Novedades de producto · noviembre","cuerpo":"Descubre los nuevos morteros de reparación estructural y las jornadas técnicas de diciembre."}'::jsonb)->>'id')::bigint AS id)
SELECT r4_aplicar_extraccion(jsonb_build_object('id', m.id, 'extraccion', '{"es_cliente":false,"motivo":"Boletín comercial de un proveedor","nombre":"","empresa":"","email":"","telefono":"","tipo_cliente":"desconocido","servicio":"No aplica","solicita":"otro","urgencia":"baja","direccion_obra":"","municipio":"","titulo":"","resumen":""}'::jsonb)) FROM m;

WITH m AS (SELECT (r4_ingest('{"canal":"whatsapp","external_id":"demo-wa-1","remitente_nombre":"Miquel Pons","remitente_tel":"+34600000202","asunto":"WhatsApp · Miquel Pons","cuerpo":"Hola, tenemos manchas de humedad que suben por las paredes de la planta baja en una casa de Llucmajor. ¿Hacéis inyecciones?"}'::jsonb)->>'id')::bigint AS id)
SELECT r4_aplicar_extraccion(jsonb_build_object('id', m.id, 'extraccion', '{"es_cliente":true,"motivo":"Particular pide información","nombre":"Miquel Pons","empresa":"Particular","email":"","telefono":"+34600000202","tipo_cliente":"particular","servicio":"Trabajos auxiliares","solicita":"informacion","urgencia":"media","direccion_obra":"","municipio":"Llucmajor","titulo":"Humedad por capilaridad en planta baja","resumen":"Vivienda en Llucmajor con humedad que sube por los muros de planta baja. Pregunta por inyecciones y plazos."}'::jsonb)) FROM m;

SELECT r4_marcar_wa(jsonb_build_object('id', (SELECT id FROM mensajes WHERE external_id = 'demo-1'), 'ok', true));
SELECT r4_marcar_wa(jsonb_build_object('id', (SELECT id FROM mensajes WHERE external_id = 'demo-2'), 'ok', false, 'detalle', 'HTTP 401 · apikey de Evolution no válida'));
SELECT r4_ingest('{"canal":"gmail","external_id":"demo-4","remitente_nombre":"Laura Ferrer","remitente_email":"laura.ferrer@estudio.example","asunto":"Refuerzo de pilar para reforma de local","cuerpo":"Necesitamos reforzar un pilar para abrir un hueco en un local de Palma."}'::jsonb);
SELECT r4_api(jsonb_build_object('op','update_inmueble','id',(SELECT id FROM inmuebles WHERE direccion = 'Av. Argentina 41'),'anio_construccion','1968','tipo_estructura','Hormigón armado'));
